/** T0 spike: the schema-bound Confect services (generated by `@confect/cli` in a Confect project). */
import {
	DatabaseReader as DatabaseReader_,
	DatabaseWriter as DatabaseWriter_,
	type DataModel,
	MutationCtx as MutationCtx_,
	QueryCtx as QueryCtx_
} from '@confect/server';
import type databaseSchema from './schema';
import type { Docs } from './schema';

type ConvexDataModel = DataModel.ToConvex<DataModel.FromSchema<typeof databaseSchema>>;

export const DatabaseReader: DatabaseReader_.DatabaseReaderTag<typeof databaseSchema, Docs> =
	DatabaseReader_.DatabaseReader<typeof databaseSchema, Docs>();
export type DatabaseReader = typeof DatabaseReader.Identifier;

export const DatabaseWriter: DatabaseWriter_.DatabaseWriterTag<typeof databaseSchema, Docs> =
	DatabaseWriter_.DatabaseWriter<typeof databaseSchema, Docs>();
export type DatabaseWriter = typeof DatabaseWriter.Identifier;

export const QueryCtx: QueryCtx_.QueryCtxTag<ConvexDataModel> =
	QueryCtx_.QueryCtx<ConvexDataModel>();
export type QueryCtx = typeof QueryCtx.Identifier;

export const MutationCtx: MutationCtx_.MutationCtxTag<ConvexDataModel> =
	MutationCtx_.MutationCtx<ConvexDataModel>();
export type MutationCtx = typeof MutationCtx.Identifier;
